def dehydrate_time(value):
    """Dehydrator for `time` values.

    Converts a time-like object to a serializable string representation.
    If the value is None, returns None. Raises TypeError if the value
    does not appear to be a time-like object. Raises ValueError if
    conversion fails for any other reason.

    :param value: The time-like object to dehydrate.
    :type value: datetime.time or similar
    :return: ISO formatted time string or None.
    """
    if value is None:
        return None

    # Check for a time-like object by looking for an isoformat method
    if not hasattr(value, "isoformat") or not callable(value.isoformat):
        raise TypeError(f"Expected a time-like object, got {type(value).__name__}")

    try:
        return value.isoformat()
    except Exception as exc:
        raise ValueError(f"Could not dehydrate time value {value!r}: {exc}") from exc

