def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    try:
        if value is None:
            return None

        # Handle dictionary representation
        if isinstance(value, dict):
            if 'x' in value and 'y' in value:
                result = {'x': value['x'], 'y': value['y']}
                if 'z' in value:
                    result['z'] = value['z']
                return result
            raise TypeError("Dictionary must contain at least 'x' and 'y' keys.")

        # Handle tuple or list representation
        if isinstance(value, (tuple, list)):
            if len(value) == 2:
                return {'x': value[0], 'y': value[1]}
            if len(value) == 3:
                return {'x': value[0], 'y': value[1], 'z': value[2]}
            raise TypeError("Tuple or list must have length 2 or 3.")

        # Handle object with attributes
        if hasattr(value, 'x') and hasattr(value, 'y'):
            result = {'x': getattr(value, 'x'), 'y': getattr(value, 'y')}
            if hasattr(value, 'z'):
                result['z'] = getattr(value, 'z')
            return result

        raise TypeError("Unsupported type for point dehydration.")
    except Exception as exc:
        raise ValueError(f"Error dehydrating point: {exc}") from exc

