def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer explicit data attribute if present
        if hasattr(self, 'data') and isinstance(self.data, dict):
            return list(self.data.keys())
        if hasattr(self, 'record') and isinstance(self.record, dict):
            return list(self.record.keys())
        # Fallback to instance dictionary
        if hasattr(self, '__dict__'):
            return list(self.__dict__.keys())
        # If no dict-like storage, return empty list
        return []
    except Exception:
        # In case of any unexpected error, return empty list
        return []

