def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Ensure the object is iterable
    try:
        iterator = iter(self)
    except TypeError as exc:
        raise TypeError("The object is not iterable") from exc

    # Search for the key
    for idx, item in enumerate(iterator):
        try:
            if item == key:
                return idx
        except Exception as exc:
            # If comparison fails, treat as non-matching
            continue

    # If we reach here, the key was not found
    raise ValueError(f"{key!r} is not in the collection")

