def values(self, *keys):
    """Return the values of the record, optionally filtering to include only certain values by index or key."""
    try:
        # Try to get the underlying data container
        data = getattr(self, "_data", None)
        if data is None:
            data = getattr(self, "data", None)
        if data is None:
            raise AttributeError("No data attribute found on the object")

        # Handle dictionary-like data
        if isinstance(data, dict):
            if not keys:
                return list(data.values())
            result = []
            values_list = list(data.values())
            for k in keys:
                if isinstance(k, int):
                    if -len(values_list) <= k < len(values_list):
                        result.append(values_list[k])
                    else:
                        raise IndexError(f"Index {k} out of range")
                else:
                    if k in data:
                        result.append(data[k])
                    else:
                        raise KeyError(f"Key {k} not found")
            return result

        # Handle list/tuple-like data
        if isinstance(data, (list, tuple)):
            if not keys:
                return list(data)
            result = []
            for k in keys:
                if isinstance(k, int):
                    if -len(data) <= k < len(data):
                        result.append(data[k])
                    else:
                        raise IndexError(f"Index {k} out of range")
                else:
                    raise TypeError(f"Unsupported key type {type(k)} for list/tuple data")
            return result

        # Unsupported data type
        raise TypeError(f"Unsupported data type {type(data)} for values extraction")

    except Exception as exc:
        raise ValueError(f"Error retrieving values: {exc}") from exc

