def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    try:
        # Determine fields and values
        if hasattr(self, "_fields") and hasattr(self, "_data"):
            fields = self._fields
            values = self._data
        else:
            # Fallback: use __dict__ but exclude private attributes
            try:
                items = [(k, v) for k, v in self.__dict__.items() if not k.startswith("_")]
            except AttributeError:
                # If __dict__ is not available, use dir
                items = [(k, getattr(self, k)) for k in dir(self)
                         if not k.startswith("_") and not callable(getattr(self, k))]
            fields = [k for k, _ in items]
            values = [v for _, v in items]
        result = {}
        if not keys:
            result = dict(zip(fields, values))
        else:
            field_to_value = dict(zip(fields, values))
            for key in keys:
                if isinstance(key, int):
                    try:
                        field = fields[key]
                        result[field] = values[key]
                    except IndexError:
                        raise
                else:
                    if key in field_to_value:
                        result[key] = field_to_value[key]
                    else:
                        result[key] = None
        return result
    except IndexError:
        raise
    except Exception as exc:
        raise RuntimeError("Error retrieving record data") from exc

