def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Validate that the object has a 'data' attribute
    if not hasattr(self, 'data'):
        raise AttributeError("Object has no 'data' attribute")
    data = self.data
    if data is None:
        raise ValueError("'data' attribute is None")
    if not isinstance(data, (list, bytearray)):
        raise TypeError("'data' must be a list or bytearray")
    if len(data) < 2:
        raise ValueError("Insufficient data to pop a 16-bit value")

    try:
        low = data.pop()
        high = data.pop()
    except Exception as exc:
        raise RuntimeError("Error popping bytes from data") from exc

    if not isinstance(high, int) or not isinstance(low, int):
        raise TypeError("Data elements must be integers")
    if not (0 <= high <= 0xFF) or not (0 <= low <= 0xFF):
        raise ValueError("Byte values must be in the range 0-255")

    return (high << 8) | low

