def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Parses a version string into a tuple of integers for simple comparison.
    Non-numeric parts are ignored. Leading 'v' or 'V' is stripped.
    Raises TypeError if the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")

    s = s.strip()
    if not s:
        return ()

    # Strip leading 'v' or 'V' if present
    if s[0] in ('v', 'V'):
        s = s[1:]

    parts = s.split('.')
    nums = []

    for part in parts:
        # Extract leading digits from each part
        digits = ''
        for ch in part:
            if ch.isdigit():
                digits += ch
            else:
                break
        if digits:
            try:
                nums.append(int(digits))
            except ValueError:
                # Should not happen, but skip if conversion fails
                continue

    return tuple(nums)

