        value = self[key]
    except Exception as exc:
        # If key lookup fails for some reason
        raise KeyError(f'Key {key!r} not found') from exc
    try:
        # Remove the key-value pair from the dictionary
        del self[key]
    except Exception as exc:
        # If deletion fails
        raise RuntimeError(f'Failed to delete key {key!r}') from exc
    return key, value

