def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with optional truncation.
    """
    try:
        if not isinstance(e, BaseException):
            raise TypeError("e must be an exception instance")
        if not isinstance(max_level, int):
            raise TypeError("max_level must be an integer")
        if not isinstance(max_path_level, int):
            raise TypeError("max_path_level must be an integer")

        import traceback, os

        tb = e.__traceback__
        if tb is None:
            return f"{type(e).__name__}: {e}"

        frames = traceback.extract_tb(tb)
        if max_level > 0:
            frames = frames[:max_level]

        lines = [f"{type(e).__name__}: {e}", "Traceback (most recent call last):"]
        for frame in frames:
            path = frame.filename
            if max_path_level > 0:
                parts = path.split(os.sep)
                if len(parts) > max_path_level:
                    path = os.sep.join(parts[-max_path_level:])
            lines.append(f'  File "{path}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f"    {frame.line.strip()}")
        return "\n".join(lines)
    except Exception as exc:
        return f"Error formatting exception: {exc}"

