def _reset_logging(cls):
    """
    Reset logging configuration to default.
    """
    try:
        root = logging.getLogger()
    except Exception:
        # logging module not available or error retrieving logger
        return

    try:
        # Remove all handlers from the root logger
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception:
                # Ignore errors while removing/closing handlers
                pass
        # Reset the root logger level to WARNING (default)
        root.setLevel(logging.WARNING)
        # Reconfigure basic logging to default settings
        logging.basicConfig(level=logging.WARNING)
    except Exception:
        # If any error occurs during reset, ignore and exit gracefully
        pass

