def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Ensure output is a list
    if output is None:
        output = []
    else:
        if not isinstance(output, list):
            try:
                output = list(output)
            except Exception:
                output = []

    # Treat a string or bytes as a single interface
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # Validate that sequence is iterable
    try:
        iter(sequence)
    except TypeError:
        raise TypeError("sequence must be an iterable or a string")

    for item in sequence:
        # If the item is a tuple or list
        if isinstance(item, (list, tuple)):
            # If it's a 2-tuple, keep as a spec pair
            if len(item) == 2:
                output.append(item)
            else:
                # Flatten nested iterables
                for sub in item:
                    output.append(sub)
        else:
            # If the item has an __interfaces__ attribute, expand it
            if hasattr(item, "__interfaces__"):
                try:
                    for iface in getattr(item, "__interfaces__"):
                        output.append(iface)
                except Exception:
                    output.append(item)
            # If the item has an interfaces attribute, expand it
            elif hasattr(item, "interfaces"):
                try:
                    for iface in getattr(item, "interfaces"):
                        output.append(iface)
                except Exception:
                    output.append(item)
            else:
                # Default: treat as a single interface
                output.append(item)

    return output

