    """
    Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset the context
        self._context = {}

        # Reinitialize bins
        initial = getattr(self, "_initial_value", None)
        if initial is not None:
            # Preserve the number of bins if they already exist
            if hasattr(self, "_bins") and isinstance(self._bins, (list, tuple)):
                self._bins = [initial for _ in self._bins]
            else:
                # If no bins exist yet, create a single bin with the initial value
                self._bins = [initial]
        else:
            # Use the make_bins method to create new bins
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self._bins = self.make_bins()
            else:
                raise AttributeError("Histogram has no 'make_bins' method to reinitialize bins.")
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc
    return None

