def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Ensure separator is a string
    try:
        sep = str(separator)
    except Exception:
        raise ValueError("separator must be convertible to string")

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(str(header))

    # Retrieve points; expect an iterable of (coordinate, value) tuples
    try:
        points_iter = iter(self.points)
    except AttributeError:
        raise AttributeError("The object has no 'points' attribute")
    except Exception as exc:
        raise ValueError(f"Unable to iterate over points: {exc}")

    for idx, point in enumerate(points_iter):
        try:
            coord, value = point
        except Exception:
            raise ValueError(f"Point at index {idx} is not a (coordinate, value) pair")

        # Convert coordinate
        if isinstance(coord, (list, tuple)):
            coord_str = sep.join(str(c) for c in coord)
        else:
            coord_str = str(coord)

        # Convert value
        if isinstance(value, (list, tuple)):
            value_str = sep.join(str(v) for v in value)
        else:
            value_str = str(value)

        lines.append(coord_str + sep + value_str)

    return "\n".join(lines)

