def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to lists to allow indexing and length checks
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError as exc:
        raise TypeError("bins and edges must be iterable") from exc

    # Basic length validation
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError(
            "edges length must be one more than bins length "
            f"(got {len(edges_list)} edges and {len(bins_list)} bins)"
        )

    total = 0.0
    for b, e_start, e_end in zip(bins_list, edges_list[:-1], edges_list[1:]):
        try:
            width = float(e_end) - float(e_start)
            value = float(b)
        except Exception as exc:
            raise ValueError(
                "bins and edges must contain numeric values"
            ) from exc
        total += value * width

    return total

