def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if not isinstance(weight, (int, float)):
        raise TypeError(f"Weight must be numeric, got {type(weight).__name__}")

    # Validate coord
    try:
        coord_iter = list(coord)
    except TypeError:
        raise TypeError(f"coord must be an iterable, got {type(coord).__name__}")

    # Retrieve histogram edges
    edges = getattr(self, "edges", None)
    if edges is None:
        raise AttributeError("Histogram has no 'edges' attribute")

    # Determine dimensionality
    if isinstance(edges, (list, tuple)):
        dims = len(edges)
    else:
        try:
            dims = edges.shape[0]
        except Exception:
            dims = 1

    if len(coord_iter) != dims:
        raise ValueError(f"coord length {len(coord_iter)} does not match histogram dimensions {dims}")

    # Find bin indices for each dimension
    indices = []
    for i, val in enumerate(coord_iter):
        # Get edges for this dimension
        edge = edges[i] if isinstance(edges, (list, tuple)) else edges[i]
        try:
            edge_list = list(edge)
        except TypeError:
            raise TypeError(f"Edge for dimension {i} is not iterable")

        # Check bounds
        if val < edge_list[0] or val > edge_list[-1]:
            return  # Outside histogram, ignore

        # Determine bin index
        if val == edge_list[-1]:
            idx = len(edge_list) - 2
        else:
            idx = None
            for j in range(len(edge_list) - 1):
                if edge_list[j] <= val < edge_list[j + 1]:
                    idx = j
                    break
            if idx is None:
                return  # Outside histogram, ignore

        indices.append(idx)

    # Increment the appropriate bin
    try:
        data = getattr(self, "data", None)
        if data is None:
            raise AttributeError("Histogram has no 'data' attribute")
        data[tuple(indices)] += weight
    except Exception:
        # Silently ignore any runtime errors (e.g., index out of bounds)
        return

