def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    class ValidationError(Exception):
        """Raised when the key does not match the expected format."""
        pass

    if not isinstance(key, str):
        raise ValidationError("Key must be a string")

    # Example validation: UUID format (8-4-4-4-12 hexadecimal digits)
    parts = key.split("-")
    if len(parts) != 5:
        raise ValidationError("Key must be in UUID format (8-4-4-4-12 hex digits)")

    expected_lengths = (8, 4, 4, 4, 12)
    hex_chars = set("0123456789abcdefABCDEF")

    for part, expected_len in zip(parts, expected_lengths):
        if len(part) != expected_len:
            raise ValidationError("Key parts have incorrect lengths")
        if not all(ch in hex_chars for ch in part):
            raise ValidationError("Key contains non-hexadecimal characters")

