def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer_schema dictionary from a Kubernetes resource dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.

    The function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.  For the top-level dictionary
    (``first_level=True``) the values of the identifying fields
    ``apiVersion``, ``kind`` and the ``metadata`` sub‑dictionary (only ``name`` and
    ``namespace``) are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")
    if not isinstance(first_level, bool):
        raise TypeError("first_level must be a bool")

    result = {}
    for key, value in manifest_dict.items():
        # Handle nested dictionaries
        if isinstance(value, dict):
            if first_level and key == "metadata":
                # Copy only identifying fields from metadata
                meta_copy = {}
                for meta_key in ("name", "namespace"):
                    if meta_key in value:
                        meta_copy[meta_key] = value[meta_key]
                result[key] = meta_copy
            else:
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Handle lists
        elif isinstance(value, list):
            result[key] = generate_default_observer_schema_list(value, first_level=False)
        # Handle scalar values
        else:
            if first_level and key in ("apiVersion", "kind"):
                result[key] = value
            else:
                result[key] = None
    return result

