def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from a tuple (kind, name, namespace) to the default observer
        schema dictionary for each resource that lacks a custom observer schema.
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    spec = getattr(app, "spec", None)
    if spec is None:
        raise ValueError("The application object does not have a 'spec' attribute.")
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        raise ValueError("The application spec does not contain a 'manifest' attribute.")
    if not isinstance(manifest, (list, tuple)):
        raise ValueError("The 'manifest' attribute must be a list or tuple of resources.")

    default_schemas = {}
    for resource in manifest:
        try:
            # Accept both dicts and objects with attributes
            if isinstance(resource, dict):
                res_dict = resource
            else:
                # Try to convert an object to a dict using its __dict__ if available
                res_dict = getattr(resource, "__dict__", {})
                if not isinstance(res_dict, dict):
                    # If we cannot obtain a dict representation, skip this resource
                    continue

            # Skip resources that already have a custom observer schema
            spec_dict = res_dict.get("spec", {})
            if isinstance(spec_dict, dict) and spec_dict.get("observer_schema"):
                continue

            # Extract required fields with safe defaults
            api_version = res_dict.get("apiVersion", "")
            kind = res_dict.get("kind", "")
            metadata = res_dict.get("metadata", {})
            if not isinstance(metadata, dict):
                metadata = {}
            name = metadata.get("name", "")
            namespace = metadata.get("namespace", "")

            # Build the default observer schema
            default_schema = {
                "apiVersion": api_version,
                "kind": kind,
                "metadata": {
                    "name": name,
                    "namespace": namespace,
                },
            }

            # Use a tuple of (kind, name, namespace) as the key
            key = (kind, name, namespace)
            default_schemas[key] = default_schema
        except Exception:
            # If any unexpected error occurs while processing a resource,
            # skip it and continue with the next one.
            continue

    return default_schemas

