        # If status is still None, provide a default message
        if status is None:
            return f"{prefix}Unknown status"
        return f"{prefix}{status}"
    except Exception as exc:
        # Return a string indicating an error occurred while retrieving status
        return f"{prefix}Error: {exc}"

