def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Basic type check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Determine spec version
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise ValueError("Instance does not have a spec_version attribute.")

        if extract_spec_version:
            type_value = inventory.get("type")
            # Mapping from type to spec version; extend as needed
            type_to_version = {"basic": "1.0", "advanced": "2.0", "pro": "3.0"}
            if type_value in type_to_version:
                spec_version = type_to_version[type_value]

        # Validate spec version
        allowed_versions = getattr(self, "allowed_spec_versions", {"1.0", "2.0", "3.0"})
        if spec_version not in allowed_versions:
            raise ValueError(f"Unsupported spec version: {spec_version}")

        # Validate required fields
        if "name" not in inventory or not isinstance(inventory["name"], str):
            raise ValueError("Inventory must contain a 'name' string.")
        if "items" not in inventory or not isinstance(inventory["items"], list):
            raise ValueError("Inventory must contain an 'items' list.")

        # Validate each item
        for idx, item in enumerate(inventory["items"]):
            if not isinstance(item, dict):
                raise ValueError(f"Item at index {idx} is not a dictionary.")
            if "id" not in item or "quantity" not in item:
                raise ValueError(f"Item at index {idx} must contain 'id' and 'quantity'.")
            if not isinstance(item["id"], (int, str)):
                raise ValueError(f"Item 'id' at index {idx} must be int or str.")
            if not isinstance(item["quantity"], int) or item["quantity"] < 0:
                raise ValueError(f"Item 'quantity' at index {idx} must be a non‑negative integer.")

        return True

    except Exception as exc:
        # Re‑raise as ValueError to keep a consistent error type
        raise ValueError(f"Inventory validation failed: {exc}") from exc

