def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate inventory type
    if inventory is None:
        raise TypeError("inventory must not be None")
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")

    # Helper to extract mapping for a given version
    def _get_version_mapping(inv, ver):
        if isinstance(inv, dict):
            # Direct mapping: version -> mapping
            if ver not in inv:
                return None
            mapping = inv[ver]
        else:  # list
            mapping = None
            for entry in inv:
                if not isinstance(entry, dict):
                    continue
                if entry.get("version") == ver:
                    mapping = entry.get("files")
                    break
        return mapping

    # Find mapping for the requested version
    current_mapping = _get_version_mapping(inventory, version)
    if current_mapping is None:
        raise ValueError(f"Version {version} not found in inventory")
    if not isinstance(current_mapping, dict):
        raise TypeError("Mapping for the requested version must be a dict")

    # Prepare result dict
    result = {}
    for logical_path, content_file in current_mapping.items():
        if logical_path is None:
            continue
        result.setdefault(logical_path, set()).add(content_file)

    # Determine later versions
    try:
        # If inventory is dict, get sorted list of versions
        if isinstance(inventory, dict):
            all_versions = sorted(inventory.keys(), key=lambda v: float(v) if isinstance(v, (int, float, str)) else v)
        else:
            all_versions = sorted(
                [entry.get("version") for entry in inventory if isinstance(entry, dict) and "version" in entry],
                key=lambda v: float(v) if isinstance(v, (int, float, str)) else v,
            )
    except Exception:
        # If sorting fails, skip later versions
        all_versions = []

    # Find index of current version
    try:
        current_index = all_versions.index(version)
    except ValueError:
        # If version not in sorted list, skip later versions
        current_index = -1

    # Add content files from later versions
    if current_index != -1:
        for later_ver in all_versions[current_index + 1 :]:
            later_mapping = _get_version_mapping(inventory, later_ver)
            if not isinstance(later_mapping, dict):
                continue
            for logical_path, content_file in later_mapping.items():
                if logical_path in result:
                    result[logical_path].add(content_file)

    return result

