def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("Manifest files must be a list, set, or tuple.")

    # Convert manifest to a set for fast lookup
    manifest_set = set(manifest_files)

    # Validate each entry in the fixity block
    for file_path, checksum in fixity.items():
        if not isinstance(file_path, str):
            raise ValueError(f"Fixity key {file_path!r} is not a string.")
        if file_path not in manifest_set:
            raise ValueError(f"File {file_path!r} in fixity block not listed in manifest.")
        if not isinstance(checksum, str):
            raise ValueError(f"Checksum for {file_path!r} is not a string.")
        if not checksum:
            raise ValueError(f"Checksum for {file_path!r} is empty.")
        # Optional: ensure checksum is hex
        if not all(c in "0123456789abcdefABCDEF" for c in checksum):
            raise ValueError(f"Checksum for {file_path!r} contains non-hex characters.")

    return True

