def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    import os
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")
    import zipfile
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            result = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                file_name = info.filename
                base = os.path.splitext(os.path.basename(file_name))[0]
                try:
                    data = zf.read(info)
                except Exception:
                    # Skip files that cannot be read
                    continue
                if base not in result:
                    result[base] = {}
                result[base][file_name] = data
            return result
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Bad zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"Error processing zip file {zip_path}: {e}") from e

