def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    # Validate inputs
    if node is None:
        return None
    if not isinstance(pubdate_xpaths, (list, tuple)):
        return None
    if not pubdate_xpaths:
        return None

    for xpath in pubdate_xpaths:
        try:
            # Execute xpath on the node
            result = node.xpath(xpath)
            if result:
                # If the result is a list of elements or strings, take the first
                first = result[0]
                # If it's an element, return its text content
                if hasattr(first, "text"):
                    text = first.text
                    if text is not None:
                        return text.strip()
                # If it's a string or other type, convert to string
                return str(first).strip()
        except Exception:
            # Ignore errors for this xpath and try the next one
            continue
    # No match found
    return None

