def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Validate hook
    if hook is None:
        raise ValueError("Hook cannot be None")
    # Ensure registry exists and is a dict
    if not hasattr(self, "_registry"):
        self._registry = {}
    if not isinstance(self._registry, dict):
        raise TypeError("Registry attribute must be a dictionary")
    # Ensure hook key exists
    try:
        handlers = self._registry.setdefault(hook, [])
    except TypeError as e:
        raise TypeError(f"Hook {hook!r} is not hashable and cannot be used as a key") from e
    def decorator(func):
        if not callable(func):
            raise TypeError(f"Handler must be callable, got {type(func).__name__}")
        try:
            handlers.append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register handler {func!r} for hook {hook!r}") from e
        return func
    return decorator

