def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to obtain the package name from the current module context
    pkg_name = __package__ or __name__
    # If the module is executed as a script, __name__ will be "__main__".
    # In that case, we attempt to infer the distribution name from the
    # package directory if possible.
    if pkg_name in ("__main__", ""):
        try:
            import os, sys
            module_file = sys.modules[__name__].__file__
            pkg_path = os.path.dirname(module_file)
            # Walk up the directory tree until we find a package marker
            while pkg_path and not os.path.isfile(os.path.join(pkg_path, "__init__.py")):
                pkg_path = os.path.dirname(pkg_path)
            if pkg_path:
                pkg_name = os.path.basename(pkg_path)
        except Exception:
            # Fallback to a generic name if inference fails
            pkg_name = None

    if not pkg_name:
        return "unknown"

    # Attempt to get the version using importlib.metadata (Python 3.8+)
    try:
        import importlib.metadata as importlib_metadata
        try:
            return importlib_metadata.version(pkg_name)
        except Exception:
            # If the distribution is not found, fall back to pkg_resources
            pass
    except Exception:
        # importlib.metadata may not be available; fall back to pkg_resources
        pass

    # Fallback to pkg_resources (setuptools)
    try:
        import pkg_resources
        return pkg_resources.get_distribution(pkg_name).version
    except Exception:
        # If all methods fail, return a default value
        return "unknown"

