def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Convert string input to a list of components
    if isinstance(pieces, str):
        pieces = pieces.split('.')
    # Ensure pieces is iterable
    try:
        iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of version components")
    # Filter out None values and convert all components to strings
    pieces = [str(p) for p in pieces if p is not None]
    if not pieces:
        return ''
    style = style.lower()
    if style == 'semver':
        # Ensure at least major.minor.patch
        major = pieces[0]
        minor = pieces[1] if len(pieces) > 1 else '0'
        patch = pieces[2] if len(pieces) > 2 else '0'
        rest = pieces[3:]
        if rest:
            # If the first rest component starts with a letter, treat it as pre‑release
            if rest[0][0].isalpha():
                return f"{major}.{minor}.{patch}{''.join(rest)}"
            else:
                return f"{major}.{minor}.{patch}.{'.'.join(rest)}"
        return f"{major}.{minor}.{patch}"
    elif style in ('pep440', 'full'):
        return '.'.join(pieces)
    elif style == 'short':
        major = pieces[0]
        minor = pieces[1] if len(pieces) > 1 else '0'
        return f"{major}.{minor}"
    elif style == 'none':
        return ''
    else:
        raise ValueError(f"Unsupported style: {style}")

