def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        if not isinstance(path, str):
            return "Invalid path type"
        if not os.path.exists(path):
            return "Path does not exist"
        if os.path.isfile(path):
            return "file"
        if os.path.isdir(path):
            # Find any file that starts with "0="
            namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
            if not namaste_files:
                return "No Namaste file found"
            # Read the first Namaste file
            namaste_path = os.path.join(path, namaste_files[0])
            try:
                with open(namaste_path, "r", encoding="utf-8") as f:
                    content = f.read().strip()
            except Exception as e:
                return f"Error reading Namaste file: {e}"
            if not content.startswith("OCFL/"):
                return "Not an OCFL directory"
            # Determine if this is a root or an object
            if os.path.isdir(os.path.join(path, "objects")):
                return "root"
            if os.path.isfile(os.path.join(path, "inventory.json")):
                return "object"
            # Fallback: if it has a Namaste file but no objects dir, treat as object
            return "object"
        return "Unknown path type"
    except Exception as e:
        return f"Error: {e}"

