def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging duplicate keys.
    """
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list")
    merged = {}
    for entry in nodes:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError("each entry must be a tuple of (ScalarNode, value)")
        key_node, value_node = entry
        # Basic validation of key_node
        if not hasattr(key_node, "value") or not hasattr(key_node, "tag"):
            raise ValueError("key must be a ScalarNode with 'value' and 'tag' attributes")
        key_val = key_node.value
        if key_val in merged:
            existing_key_node, existing_value_node = merged[key_val]
            # Determine if both values are MappingNodes
            is_existing_map = (
                hasattr(existing_value_node, "tag")
                and existing_value_node.tag == "tag:yaml.org,2002:map"
            )
            is_new_map = (
                hasattr(value_node, "tag") and value_node.tag == "tag:yaml.org,2002:map"
            )
            if is_existing_map and is_new_map:
                # Merge mapping values recursively
                merged_map_value = deep_merge_nodes(
                    existing_value_node.value + value_node.value
                )
                # Update the existing mapping node in place
                existing_value_node.value = merged_map_value
                merged[key_val] = (existing_key_node, existing_value_node)
            else:
                # Last value wins
                merged[key_val] = (key_node, value_node)
        else:
            merged[key_val] = (key_node, value_node)
    return list(merged.values())

