def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class as argument")
    result = set()
    def _collect(c):
        try:
            subs = c.__subclasses__()
        except Exception as exc:
            raise RuntimeError(f"Failed to get subclasses of {c}") from exc
        for sub in subs:
            if sub not in result:
                result.add(sub)
                _collect(sub)
    try:
        _collect(cls)
    except RecursionError as exc:
        raise RuntimeError(f"Recursion depth exceeded while collecting subclasses of {cls}") from exc
    return result

