def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Pattern matches a string that starts and ends with the same quote character
    # (either single or double) and captures the content in between.
    import re
    pattern = re.compile(r"^(['\"])(.*)\1$")
    match = pattern.match(name)
    if match:
        return match.group(2)
    return name

