def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Validate input
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Direct string checks for common localhost representations
    lower_host = host.lower()
    if lower_host == "localhost" or lower_host == "localhost.":
        return True
    if host in ("127.0.0.1", "::1"):
        return True

    # Handle host strings that may include a port (e.g., "localhost:80")
    if ":" in host and not host.startswith("[") and not host.endswith("]"):
        # Split on the last colon to separate host and port
        host_part = host.rsplit(":", 1)[0]
        if host_part.lower() == "localhost" or host_part in ("127.0.0.1", "::1"):
            return True
        host = host_part

    try:
        # Resolve the host to IP addresses
        infos = socket.getaddrinfo(host, None)
        for info in infos:
            addr = info[4][0]
            if addr == "127.0.0.1" or addr == "::1":
                return True
    except socket.gaierror:
        # Host could not be resolved
        return False
    except Exception:
        # Any other unexpected error
        return False

    return False

