def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine the variable name and optional default value from the matcher
    name = None
    default = None

    if matcher is None:
        raise ValueError("Matcher cannot be None")

    # Handle string matcher: "VAR" or "VAR:default"
    if isinstance(matcher, str):
        parts = matcher.split(':', 1)
        name = parts[0]
        if len(parts) == 2:
            default = parts[1]

    # Handle tuple/list matcher: (name,) or (name, default)
    elif isinstance(matcher, (tuple, list)):
        if not matcher:
            raise ValueError("Matcher tuple/list cannot be empty")
        name = matcher[0]
        if len(matcher) > 1:
            default = matcher[1]

    # Handle dict matcher: {'name': 'VAR', 'default': 'def'}
    elif isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError("Matcher dict must contain a 'name' key")
        name = matcher['name']
        default = matcher.get('default')

    # Handle regex match object: group(1) is name, group(2) is default if present
    elif hasattr(matcher, 'group'):
        try:
            name = matcher.group(1)
        except Exception:
            raise ValueError("Matcher match object does not have group 1")
        try:
            default = matcher.group(2)
        except Exception:
            default = None

    else:
        raise TypeError(f"Unsupported matcher type: {type(matcher)}")

    if name is None:
        raise ValueError("Variable name could not be determined from matcher")

    # Retrieve the environment variable
    value = os.getenv(name)
    if value is not None:
        return value

    # If not set, use default if provided
    if default is not None:
        return default

    # Neither set nor default: raise an error
    raise KeyError(f"Environment variable '{name}' not found and no default provided.")

