    """
    This method converts the given string to regex pattern
    """
    if not isinstance(strip, bool):
        raise TypeError("strip must be a boolean")
    if pattern is None:
        raise ValueError("pattern cannot be None")
    # If pattern is already a compiled regex, return it
    compiled_type = type(re.compile(''))
    if isinstance(pattern, compiled_type):
