def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        result = yaml.dump(obj, Dumper=dumper)
    except Exception as exc:
        raise ValueError("Failed to dump object to YAML string: %s" % exc)
    unicode_type = type(u"")
    bytes_type = type(b"")
    if isinstance(result, bytes_type) and not isinstance(result, unicode_type):
        try:
            result = result.decode('utf-8')
        except Exception as exc:
            raise ValueError("Failed to decode YAML bytes: %s" % exc)
    if not isinstance(result, unicode_type):
        try:
            result = unicode_type(result)
        except Exception as exc:
            raise ValueError("Failed to convert YAML output to unicode: %s" % exc)
    return result

