def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        if x is None:
            raise ValueError("Input cannot be None.")
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input must be a numeric type or array-like of numeric types.") from e
    if np.iscomplexobj(x_arr):
        raise ValueError("Input must be real-valued.")
    mu = 0.2
    sigma = 0.1
    try:
        result = np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise RuntimeError("Error computing Gaussian.") from e
    return result

