def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re
    configs = {}
    errors = []

    # Regular expression to find ${VAR} patterns
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            def repl(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            return env_pattern.sub(repl, value)
        return value

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(_resolve_env_in_value(v)) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(_resolve_env_in_value(item)) for item in d]
        else:
            return _resolve_env_in_value(d)

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    msg = f"JSON decode error in file '{filename}': {e}"
                    record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                    errors.append(record)
                    continue

                if not isinstance(data, dict):
                    msg = f"Configuration in file '{filename}' is not a JSON object."
                    record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
                    errors.append(record)
                    continue

                if resolve_env:
                    data = _resolve_env_in_dict(data)

                if overrides:
                    # Simple shallow merge; overrides take precedence
                    data.update(overrides)

                configs[filename] = data

        except FileNotFoundError as e:
            msg = f"File not found: '{filename}'."
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            errors.append(record)
        except Exception as e:
            msg = f"Unexpected error loading file '{filename}': {e}"
            record = logging.LogRecord('config_loader', logging.ERROR, filename, 0, msg, None, None)
            errors.append(record)

    return configs, errors

