def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type, return it directly
    if isinstance(seq, (list, tuple, str, bytes, bytearray, memoryview)):
        return seq, type(seq)

    # If seq is a file-like object with a read method, read its contents
    if hasattr(seq, "read"):
        try:
            if bufsize is None:
                data = seq.read()
            else:
                chunks = []
                while True:
                    chunk = seq.read(bufsize)
                    if not chunk:
                        break
                    chunks.append(chunk)
                # Join chunks appropriately
                if chunks and isinstance(chunks[0], (bytes, bytearray)):
                    data = b"".join(chunks)
                else:
                    data = "".join(chunks)
            return data, type(data)
        except Exception:
            # If reading fails, fall back to other strategies
            pass

    # If seq has a readlines method, use it to get a list of lines
    if hasattr(seq, "readlines"):
        try:
            lines = seq.readlines()
            return lines, type(lines)
        except Exception:
            pass

    # Try to convert seq to a list (handles iterators/generators)
    try:
        seq_list = list(seq)
        return seq_list, type(seq_list)
    except TypeError:
        # seq is not iterable
        raise TypeError(f"Object {seq!r} is not a sequence or iterable") from None
    except Exception as exc:
        # Other unexpected errors
        raise RuntimeError(f"Failed to process sequence: {exc}") from exc

