        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return current scale if no new scale is requested
        if other is None:
            return self._scale

        # Validate that the new scale is numeric
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value")

        # Validate that the current scale is known and non‑zero
        if self._scale is None:
            raise LenaValueError("Cannot rescale: current scale is unknown")
        if not isinstance(self._scale, (int, float)):
            raise LenaValueError("Current scale is not numeric")
        if self._scale == 0:
            raise LenaValueError("Cannot rescale: current scale is zero")

        # Compute the scaling factor
        try:
            factor = other / self._scale
        except ZeroDivisionError:
            raise LenaValueError("Cannot rescale: current scale is zero")

        # Ensure the factor is a finite number
        if factor != factor or factor == float("inf") or factor == -float("inf"):
            raise ValueError("Computed scaling factor is not finite")

        # Ensure there is at least one field to rescale
        if not hasattr(self, "_fields") or not self._fields:
            raise LenaValueError("Graph has no fields to rescale")

