            # If data is a list, perform element‑wise multiplication
            if isinstance(data, list):
                self._data[last_field] = [v * factor for v in data]
            else:
                # Assume array‑like (e.g., numpy) where * works element‑wise
                self._data[last_field] = data * factor
        except Exception as exc:
            raise LenaValueError(
                f"Error rescaling data for field '{last_field}': {exc}"
            ) from exc

        # Rescale the errors for the last field, if present
        if hasattr(self, "_errors") and last_field in self._errors:
