def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases iterable
    try:
        bases = tuple(bases)
    except Exception:
        raise TypeError("bases must be an iterable of classes")
    # Ensure each base is a class
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"base {b!r} is not a class")
    # If an explicit metaclass is provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")
        if not issubclass(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a subclass of type")
        for b in bases:
            base_meta = type(b)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"explicit metaclass {explicit_mc!r} is not compatible with base {b!r} metaclass {base_meta!r}"
                )
        return explicit_mc
    # No explicit metaclass: determine the most derived metaclass
    if not bases:
        return type
    metas = [type(b) for b in bases]
    most_derived = None
    for candidate in metas:
        if all(issubclass(candidate, other) for other in metas):
            if most_derived is not None:
                raise TypeError("metaclass conflict: multiple metaclasses are equally derived")
            most_derived = candidate
    if most_derived is None:
        raise TypeError("metaclass conflict: no metaclass is a subclass of all others")
    return most_derived

