def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the cache has the expected attributes
    if not hasattr(self, "freq_map") or not hasattr(self, "key_map"):
        raise AttributeError("Cache object missing required attributes.")
    if not self.freq_map:
        raise KeyError("popitem from an empty cache")
    # Identify the current minimum frequency
    min_freq = self.min_freq
    # Retrieve the OrderedDict (or similar) of keys for this frequency
    key_order = self.freq_map.get(min_freq)
    if not key_order:
        # Inconsistent state: no keys for the recorded min_freq
        raise KeyError("No items found for the minimum frequency.")
    # Pop the oldest key in this frequency bucket
    try:
        key, _ = key_order.popitem(last=False)
    except Exception as exc:
        raise KeyError("Failed to pop item from frequency bucket.") from exc
    # Retrieve the value and original frequency from the key map
    try:
        value, freq = self.key_map.pop(key)
    except KeyError as exc:
        # Inconsistent state: key not found in key_map
        raise KeyError(f"Key {key!r} not found in key map.") from exc
    # If the frequency bucket is now empty, remove it and adjust min_freq
    if not key_order:
        del self.freq_map[min_freq]
        if self.freq_map:
            # Set min_freq to the smallest remaining frequency
            self.min_freq = min(self.freq_map.keys())
        else:
            # Cache is now empty
            self.min_freq = 0
    return key, value

