def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("Provided node is not an XML element with iterable children") from exc
    result = {}
    for child in children:
        try:
            tag = child.tag
        except Exception:
            # Skip nodes that do not have a tag attribute
            continue
        result[tag] = child
    return result

