def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not isinstance(document, str) or not document.strip():
        raise ValueError("Document must be a non-empty string")
    doc = document.strip()
    try:
        if doc.startswith('{'):
            # JSON format
            data = __import__('json').loads(doc)
            subject = data.get('subject')
            aliases = data.get('aliases', [])
            links = data.get('links', [])
            if not isinstance(subject, str):
                raise ValueError("JSON webfinger missing or invalid 'subject'")
            if not isinstance(aliases, list):
                raise ValueError("'aliases' must be a list")
            if not isinstance(links, list):
                raise ValueError("'links' must be a list")
            for link in links:
                if not isinstance(link, dict):
                    raise ValueError("Each link must be a dict")
            return {'subject': subject, 'aliases': aliases, 'links': links}
        else:
            # XRD format
            ET = __import__('xml.etree.ElementTree')
            root = ET.fromstring(doc)
            subject = None
            aliases = []
            links = []
            for elem in root.iter():
                tag = elem.tag
                if tag.endswith('Subject'):
                    if elem.text:
                        subject = elem.text.strip()
                elif tag.endswith('Alias'):
                    if elem.text:
                        aliases.append(elem.text.strip())
                elif tag.endswith('Link'):
                    link = {}
                    for attr in ['rel', 'type', 'href', 'template', 'title', 'profile']:
                        if attr in elem.attrib:
                            link[attr] = elem.attrib[attr]
                    if link:
                        links.append(link)
            if not subject:
                raise ValueError("XRD missing Subject")
            return {'subject': subject, 'aliases': aliases, 'links': links}
    except Exception as e:
        raise ValueError(f"Failed to parse Diaspora webfinger: {e}") from e

