def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Basic validation of handle format
        if '@' not in handle:
            return None
        local_part, domain = handle.split('@', 1)
        if not local_part or not domain:
            return None

        # Construct the WebFinger URL
        resource = f'acct:{handle}'
        import urllib.parse
        import urllib.request
        query = urllib.parse.urlencode({'resource': resource})
        url = f'https://{domain}/.well-known/webfinger?{query}'

        # Prepare the request with appropriate Accept header
        req = urllib.request.Request(
            url,
            headers={'Accept': 'application/jrd+json, application/json'}
        )

        # Perform the request with a timeout
        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status != 200:
                return None
            return response.read().decode('utf-8')
    except Exception:
        # Any error (network, parsing, etc.) results in None
        return None

