    if not isinstance(host, str) or not host.strip():
        raise ValueError("host must be a non-empty string")

    # Normalise host to a base URL
    base = host.strip()
    if not base.startswith(("http://", "https://")):
        base = f"https://{base}"
    base = base.rstrip("/")
    url = f"{base}/.well-known/host-meta"

