def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: content of spec file (string or dict)
    :raise IRValidatorException: when mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    # Ensure we have some content to work with
    if spec_content is None:
        raise IRValidatorException("Spec content is None")

    # Load the content into a dictionary
    if isinstance(spec_content, str):
        try:
            # yaml.safe_load is expected to be available in the module's namespace
            data = yaml.safe_load(spec_content)
        except Exception as exc:
            raise IRValidatorException(f"Failed to parse YAML content: {exc}")
    elif isinstance(spec_content, dict):
        data = spec_content
    else:
        raise IRValidatorException(
            f"Spec content must be a string or a dictionary, got {type(spec_content).__name__}"
        )

    # The parsed data must be a dictionary
    if not isinstance(data, dict):
        raise IRValidatorException(
            f"Parsed spec is not a dictionary, got {type(data).__name__}"
        )

    # Define the mandatory fields that must be present in the spec
    required_fields = ["name", "version", "spec"]
    missing_fields = [field for field in required_fields if field not in data]
    if missing_fields:
        raise IRValidatorException(
            f"Missing required fields in spec: {', '.join(missing_fields)}"
        )

    return data

