def get_silent_args(self, args):
    """
    Return a list of argument names that are considered "silenced".
    An argument is considered silenced if its value is None, an empty string,
    or the boolean False. If args is a list of tuples, each tuple should
    contain (name, value). If args is a list of names only, all names are
    treated as silenced. Unsupported types raise a TypeError.
    """
    try:
        if args is None:
            return []

        # Handle dictionary of arguments
        if isinstance(args, dict):
            return [name for name, value in args.items()
                    if value is None or value == '' or value is False]

        # Handle list of arguments
        if isinstance(args, list):
            silent = []
            for item in args:
                # Tuple form: (name, value)
                if isinstance(item, tuple) and len(item) == 2:
                    name, value = item
                    if value is None or value == '' or value is False:
                        silent.append(name)
                else:
                    # Treat any other item as a name with no value
                    silent.append(item)
            return silent

        # Unsupported type
        raise TypeError("args must be a dict or list")

    except Exception:
        # In case of unexpected errors, return an empty list
        return []

