def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        def _evaluate(cond, args_dict):
            """Evaluate a single condition against args_dict."""
            if cond is None:
                return False
            if isinstance(cond, bool):
                return cond
            if callable(cond):
                try:
                    return bool(cond(args_dict))
                except Exception:
                    return False
            # Treat as string expression
            try:
                return bool(eval(cond, {}, args_dict))
            except Exception:
                return False

        if not isinstance(args, dict):
            # If args is not a dict, try to convert to dict of attributes
            try:
                args = vars(args)
            except Exception:
                args = {}

        required = []
        for opt in options_spec:
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            # Support list/tuple of conditions: any true triggers requirement
            if isinstance(cond, (list, tuple)):
                match = any(_evaluate(c, args) for c in cond)
            else:
                match = _evaluate(cond, args)
            if match:
                required.append(name)
        return required

