def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary mapping argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Retrieve a mapping of argument names to maximum allowed lengths, if available
    max_lengths = getattr(self, "max_lengths", {})
    if not isinstance(max_lengths, dict):
        max_lengths = {}

    for name, value in args.items():
        # Determine the maximum length for this argument
        max_len = max_lengths.get(name)
        if max_len is None:
            # Fallback: check if the value itself defines a max_length attribute
            max_len = getattr(value, "max_length", None)

        # If no length constraint is defined, skip this argument
        if max_len is None:
            continue

        # Ensure the max_len is a non-negative integer
        if not isinstance(max_len, int) or max_len < 0:
            continue

        # Helper function to validate a single string-like value
        def _check_string(val, context):
            try:
                length = len(val)
            except Exception:
                return  # Cannot determine length; skip
            if length > max_len:
                raise ValueError(f"Argument '{context}' length {length} exceeds maximum allowed {max_len}")

        # Validate based on the type of the value
        if isinstance(value, str):
            _check_string(value, name)
        elif isinstance(value, (bytes, bytearray)):
            _check_string(value, name)
        elif isinstance(value, (list, tuple)):
            for idx, item in enumerate(value):
                if isinstance(item, (str, bytes, bytearray)):
                    _check_string(item, f"{name}[{idx}]")
        elif isinstance(value, dict):
            for subkey, subvalue in value.items():
                if isinstance(subvalue, (str, bytes, bytearray)):
                    _check_string(subvalue, f"{name}.{subkey}")
        else:
            # For other types, attempt to use __len__ if available
            try:
                length = len(value)
                if length > max_len:
                    raise ValueError(f"Argument '{name}' length {length} exceeds maximum allowed {max_len}")
            except Exception:
                # If length cannot be determined, skip validation for this value
                pass

    return True

