    :param args: The received arguments.
    """
    # Allow None or empty arguments
    if args is None:
        return True

    # Try to convert Namespace-like objects to dict
    if not isinstance(args, dict):
        try:
            args = vars(args)
        except Exception:
            raise TypeError("args must be a dict or an object with a __dict__ attribute")

    # Ensure the class has a choices mapping
    if not hasattr(self, "choices") or not isinstance(self.choices, dict):
        raise AttributeError("self.choices must be defined as a dict mapping argument names to allowed values")

    for key, value in args.items():
        # Skip arguments that have no defined choices
        if key not in self.choices:
            continue

        allowed = self.choices[key]
        if not isinstance(allowed, (list, tuple, set)):
            raise ValueError(f"Choices for argument '{key}' must be a list, tuple, or set")

        # If the value itself is an iterable (but not a string), validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value '{v}' for argument '{key}'. Allowed: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{key}'. Allowed: {allowed}"
                )

    return True

