def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :raises ValueError: If args is invalid or value not in [min, max].
    :raises TypeError: If args is not a dict or values are not numeric.
    :raises KeyError: If required keys are missing.
    :return: True if validation passes.
    """
    if args is None:
        raise ValueError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    required_keys = {"min", "max", "value"}
    missing = required_keys - args.keys()
    if missing:
        raise KeyError(f"Missing required argument(s): {', '.join(sorted(missing))}")
    min_val = args["min"]
    max_val = args["max"]
    val = args["value"]
    for name, v in (("min", min_val), ("max", max_val), ("value", val)):
        if v is None:
            raise ValueError(f"Argument '{name}' cannot be None")
        if not isinstance(v, (int, float)):
            raise TypeError(f"Argument '{name}' must be a number")
    if min_val > max_val:
        raise ValueError(f"Minimum value {min_val} cannot be greater than maximum value {max_val}")
    if not (min_val <= val <= max_val):
        raise ValueError(f"Value {val} is not between {min_val} and {max_val}")
    return True

