def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: stdout string from ansible-playbook execution
    :raises RuntimeError: if the command fails or inputs are invalid
    """
    # Import required modules locally to avoid top-level imports
    import subprocess
    import json
    import os

    # Validate playbook_path
    if not isinstance(playbook_path, str):
        raise RuntimeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise RuntimeError(f"Playbook file not found: {playbook_path}")

    # Build the base command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity
    if verbose is not None:
        try:
            level = int(verbose)
            if level > 0:
                cmd.append("-" + "v" * level)
        except (ValueError, TypeError):
            # Ignore invalid verbosity values
            pass

    # Add extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise RuntimeError("extra_vars must be a dictionary")
        try:
            json_vars = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", json_vars])
        except (TypeError, ValueError) as e:
            raise RuntimeError(f"Failed to serialize extra_vars: {e}")

    # Add ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise RuntimeError("ansible_args must be a dictionary")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise RuntimeError(f"Argument key must be a string: {key}")
            # Ensure key starts with '--'
            if not key.startswith("--"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
                # If False, skip adding the flag
            elif value is None:
                # Skip None values
                continue
            else:
                cmd.extend([key, str(value)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as e:
        # Include stderr in the error message
        raise RuntimeError(
            f"ansible-playbook failed with exit code {e.returncode}:\n{e.stderr}"
        ) from e
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Ensure Ansible is installed.")

    # Return stdout
    return result.stdout

