def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define parser‑specific type hints (extend as needed)
    type_map = {
        'virsh': {'timeout': int, 'debug': bool},
        'ospd': {'port': int, 'verbose': bool},
        'main': {'count': int, 'enabled': bool},
    }

    def _to_bool(val):
        return val.lower() in ('true', '1', 'yes', 'y')

    def _to_int(val):
        return int(val)

    def _to_float(val):
        return float(val)

    def _to_list(val):
        return [item.strip() for item in val.split(',') if item.strip()]

    for key, raw_val in list(values_dict.items()):
        # Skip non‑string values or None
        if raw_val is None or not isinstance(raw_val, str):
            continue

        val = raw_val.strip()
        # Skip empty strings
        if not val:
            continue

        # Determine target type
        target_type = None
        if parser_name in type_map and key in type_map[parser_name]:
            target_type = type_map[parser_name][key]

        # If no explicit type, try heuristics
        if target_type is None:
            # Boolean
            if val.lower() in ('true', 'false', '1', '0', 'yes', 'no', 'y', 'n'):
                target_type = bool
            # Integer
            elif val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
                target_type = int
            # Float
            else:
                try:
                    float(val)
                    target_type = float
                except ValueError:
                    target_type = None

        # Perform conversion
        try:
            if target_type is bool:
                values_dict[key] = _to_bool(val)
            elif target_type is int:
                values_dict[key] = _to_int(val)
            elif target_type is float:
                values_dict[key] = _to_float(val)
            elif target_type is list:
                values_dict[key] = _to_list(val)
            else:
                # Heuristic list detection
                if ',' in val:
                    values_dict[key] = _to_list(val)
                else:
                    # Keep as string
                    values_dict[key] = val
        except Exception:
            # On any conversion error, leave the original string
            values_dict[key] = raw_val

