def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate input
    try:
        os = __import__('os')
        if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
            return {}
    except Exception:
        return {}

    # Determine spec file path
    spec_file = None
    try:
        json_path = os.path.join(plugin_dir, 'plugin_spec.json')
        if os.path.isfile(json_path):
            spec_file = json_path
        else:
            yaml_path = os.path.join(plugin_dir, 'plugin_spec.yaml')
            if os.path.isfile(yaml_path):
                spec_file = yaml_path
    except Exception:
        return {}

    if not spec_file:
        return {}

    # Load spec content
    spec_data = {}
    try:
        if spec_file.endswith('.json'):
            json = __import__('json')
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec_data = json.load(f)
        elif spec_file.endswith('.yaml') or spec_file.endswith('.yml'):
            try:
                yaml = __import__('yaml')
                with open(spec_file, 'r', encoding='utf-8') as f:
                    spec_data = yaml.safe_load(f)
            except Exception:
                # YAML parsing failed; try to load as JSON fallback
                json = __import__('json')
                with open(spec_file, 'r', encoding='utf-8') as f:
                    spec_data = json.load(f)
    except Exception:
        return {}

    if not isinstance(spec_data, dict):
        return {}

    # Flatten the dictionary
    try:
        flat_dict = _flatten(spec_data)
    except Exception:
        return {}

    return flat_dict

