def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    try:
        # Ensure the instance has a config_path attribute
        if not hasattr(self, "config_path"):
            raise AttributeError("Missing 'config_path' attribute on the instance.")
        # Validate the config_path value
        if not self.config_path:
            raise ValueError("The 'config_path' attribute is empty or None.")
        # Inject the environment variable only if it is not already set
        if "CONFIG_PATH" not in os.environ:
            os.environ["CONFIG_PATH"] = self.config_path
    except Exception as exc:
        # Wrap any exception in a RuntimeError to provide context
        raise RuntimeError(f"Failed to inject config path: {exc}") from exc

